// cashMinor is the checked aggregate, never an additional spendable wallet.
const {add,number}=require('./autonomous-economy.cjs');
const emptyFlows=()=>({wages:0,payout:0,sales:0,spending:0,migrationIn:0,migrationOut:0,capitalFunding:0});
function enable(e,population){if(!e?.householdEconomy)return;const counts=new Map();for(const c of population.cohorts){if(!counts.has(c.territoryId))counts.set(c.territoryId,{rural:0,urban:0});const row=counts.get(c.territoryId);row[c.settlement]=add(row[c.settlement],c.count);}for(const h of e.households)if(!h.accounts){const p=counts.get(h.provinceId)||{rural:0,urban:0},total=add(p.rural,p.urban),rural=total?number(BigInt(h.cashMinor)*BigInt(p.rural)/BigInt(total)):h.cashMinor;h.accounts={version:1,rural:{cashMinor:rural,income:0},urban:{cashMinor:h.cashMinor-rural,income:0}};}for(const h of e.households)for(const sector of ['rural','urban'])h.accounts[sector].flows??=emptyFlows();const houses=new Map(e.households.map(h=>[h.id,h]));for(const f of e.enterprises)if(!Object.hasOwn(f.ownerRef,'sector')&&houses.get(f.ownerRef.id)?.accounts){const h=houses.get(f.ownerRef.id),p=counts.get(h.provinceId);f.ownerRef.sector=p?.urban?'urban':'rural';}}
function validate(h){if(!Object.hasOwn(h,'accounts'))return;const a=h.accounts,safe=n=>Number.isSafeInteger(n)&&n>=0;if(!a||Object.getPrototypeOf(a)!==Object.prototype||Object.keys(a).length!==3||a.version!==1||['rural','urban'].some(k=>!a[k]||Object.getPrototypeOf(a[k])!==Object.prototype||Object.keys(a[k]).length!==(Object.hasOwn(a[k],'flows')?3:2)||!safe(a[k].cashMinor)||!safe(a[k].income))||add(a.rural.cashMinor,a.urban.cashMinor)!==h.cashMinor)throw Error('Household accounts: invalid balances');for(const sector of ['rural','urban'])if(a[sector].flows){const f=a[sector].flows,k=Object.keys(emptyFlows());if(Object.getPrototypeOf(f)!==Object.prototype||Object.keys(f).length!==k.length||k.some(key=>!safe(f[key])))throw Error('Household accounts: invalid flows');}}
function cash(h,sector='urban'){return h.accounts?h.accounts[sector].cashMinor:h.cashMinor;}
function debit(h,value,sector='urban',kind='spending'){const available=cash(h,sector);if(!Number.isSafeInteger(value)||value<0||value>available)throw Error('Household accounts: insufficient cash');if(h.accounts){const account=h.accounts[sector];if(account.flows)account.flows[kind]=add(account.flows[kind],value);account.cashMinor-=value;}h.cashMinor-=value;}
function credit(h,value,sector='urban',income=true,kind='sales'){if(!Number.isSafeInteger(value)||value<0)throw Error('Household accounts: invalid payment');const total=add(h.cashMinor,value),account=h.accounts?.[sector],balance=account?add(account.cashMinor,value):0,earned=account&&income?add(account.income,value):0,flow=account?.flows?add(account.flows[kind],value):0;h.cashMinor=total;if(account){account.cashMinor=balance;if(income)account.income=earned;if(account.flows)account.flows[kind]=flow;}}
function transfer(from,to,value,fromSector='urban',toSector='urban',kind='sales'){
  if(!Number.isSafeInteger(value)||value<0||value>cash(from,fromSector))throw Error('Household accounts: insufficient cash');
  if(from!==to)add(to.cashMinor,value);
  if(to.accounts){add(to.accounts[toSector].cashMinor-(from===to&&fromSector===toSector?value:0),value);add(to.accounts[toSector].income,value);if(to.accounts[toSector].flows)add(to.accounts[toSector].flows[kind],value);}
  debit(from,value,fromSector);credit(to,value,toSector,true,kind);
}
function labor(e,population){const totals=new Map(),rural=new Map();for(const c of population.cohorts){totals.set(c.territoryId,add(totals.get(c.territoryId)||0,c.count));if(c.settlement==='rural')rural.set(c.territoryId,add(rural.get(c.territoryId)||0,c.count));}return new Map(e.households.map(h=>{const total=number(BigInt(totals.get(h.provinceId)||0)*BigInt(e.rules.laborParticipationBps)/10000n),r=number(BigInt(rural.get(h.provinceId)||0)*BigInt(e.rules.laborParticipationBps)/10000n);return [h.provinceId,{rural:r,urban:total-r}];}));}
function takeLabor(pool,workers,preferred='urban'){if(!Number.isSafeInteger(workers)||workers<0||!['urban','rural'].includes(preferred)||['rural','urban'].some(k=>!Number.isSafeInteger(pool[k])||pool[k]<0))throw Error('Household accounts: invalid labor');const other=preferred==='urban'?'rural':'urban',first=Math.min(workers,pool[preferred]),second=workers-first;if(second>pool[other])throw Error('Household accounts: labor exhausted');pool[preferred]-=first;pool[other]-=second;return {[preferred]:first,[other]:second};}
function payroll(from,h,workers,amount,pool,preferred='urban'){
  if(!Number.isSafeInteger(amount)||amount<0)throw Error('Household accounts: invalid payment');
  const projected={...pool},used=takeLabor(projected,workers,preferred),rural=workers?number(BigInt(amount)*BigInt(used.rural)/BigInt(workers)):0;
  if(amount>cash(from))throw Error('Household accounts: insufficient cash');add(h.cashMinor,amount);
  if(h.accounts)for(const [sector,value]of [['rural',rural],['urban',amount-rural]]){add(h.accounts[sector].cashMinor,value);add(h.accounts[sector].income,value);if(h.accounts[sector].flows)add(h.accounts[sector].flows.wages,value);}
  Object.assign(pool,projected);debit(from,amount);credit(h,rural,'rural',true,'wages');credit(h,amount-rural,'urban',true,'wages');return used;
}
function migrate(h,quantity,ruralPopulation){if(!h?.accounts||!quantity)return;const value=number(BigInt(h.accounts.rural.cashMinor)*BigInt(quantity)/BigInt(Math.max(1,ruralPopulation)));debit(h,value,'rural','migrationOut');credit(h,value,'urban',false,'migrationIn');}
module.exports={enable,validate,cash,debit,credit,transfer,labor,takeLabor,payroll,migrate};
